-- =============================================================================
-- StaziaMed, CARGA DAS PROVAS CORRIGIDAS, parte 2 (Revalida 2026/1, revalida-2026-1): texto fiel ao caderno oficial do Inep.
-- Gerado por scripts/carga-provas/gerar-correcoes.mjs (ramo carga-provas). Não edite à mão.
-- O que faz: 45 correções de texto em 35 questões (35 campos: enunciado ou alternativa).
--   * Cada campo só é trocado se o texto no banco ainda é EXATAMENTE o de 12/10/2026 (o que a revisão comparou com o PDF).
--     Se alguém mudou esse texto depois, o campo é PULADO e aparece na lista do fim. Nada é apagado.
--   * O texto antigo fica no histórico da questão (Administração > Questões > Editar > Ver histórico de mudanças), com o motivo.
--   * NÃO mexe em gabarito, situação (anulada), explicações, conduta esperada, "o que a questão avalia", tema, figuras.
--   * Regra do sistema (migração 9500): se a questão tinha Análise Stazia publicada, ela sai do ar (explicava o texto antigo);
--     a contagem aparece no fim.
-- Como colar: editor SQL do Supabase, o arquivo INTEIRO, Run. A primeira linha do resultado começa com "OK:" (ou "ATENÇÃO:" se
-- algum campo foi pulado; mostre ao Claude). Pode colar de novo: a segunda vez não muda nada.
-- =============================================================================
create temp table if not exists _carga_texto_resultado (prova text, questao text, codigo text, campo text, situacao text);
delete from _carga_texto_resultado where prova = 'revalida-2026-1';

do $carga_texto$
declare
  v_dados constant jsonb := $carga_dados$[{"id":"revalida_2026_1_q003","code":"REV-2026.1-Q003","campos":{"statement":{"antes_md5":"6ef94d7558bd67c0d64427a52438a022","depois":"Mulher de 88 anos é trazida à Unidade de Pronto Atendimento (UPA) pelo SAMU, com queixa de dor intensa em quadril direito após queda da própria altura. Possui antecedentes de hipertensão arterial sistêmica e diabetes mellitus, em acompanhamento regular. Nega outras comorbidades ou uso prévio de psicotrópicos. É diagnosticada com fratura de colo de fêmur e aguarda transferência hospitalar. Apresenta dor significativa no quadril, exacerbada à mobilização passiva, a despeito da administração de dipirona endovenosa. Após 6 horas na UPA, evolui com desatenção, agitação psicomotora alternada com apatia e discurso desconexo, com tomografia de crânio normal. Exame físico: PA 138 x 76 mmHg; FC 102 bpm; FR 22 irpm; Temperatura 36,5 °C; SpO₂ 94% em ar ambiente; glicemia capilar 120 mg/dL. Pupilas isocóricas e fotorreagentes; ausculta cardiopulmonar sem alterações; abdome indolor e sem visceromegalias; ausência de déficits neurológicos focais. Considerando o quadro clínico apresentado, o(s) principal(is) fator(es) precipitante(s) é(são)"}}},{"id":"revalida_2026_1_q007","code":"REV-2026.1-Q007","campos":{"statement":{"antes_md5":"d2742d517e480319b02c864fed8f0f88","depois":"Mulher de 38 anos, com diagnósticos de hipertensão arterial sistêmica, diabetes mellitus e transtorno afetivo bipolar, comparece à consulta médica com discurso desconexo, tremor grosseiro em extremidades e marcha atáxica, iniciada há alguns dias. Faz uso regular de captopril, metformina, carbonato de lítio e recentemente foi introduzida hidroclorotiazida devido a descontrole pressórico. Ao exame clínico, apresenta-se normocorada; desidratada (1+/4+); anictérica; afebril; PA 140 x 90 mmHg; FC 98 bpm e glicemia capilar 95 mg/dL. Nesse contexto, qual é a medida terapêutica mais indicada para o quadro atual?"}}},{"id":"revalida_2026_1_q008","code":"REV-2026.1-Q008","campos":{"statement":{"antes_md5":"a523b12e38859fcf4949a626f706a115","depois":"Mulher, 58 anos, residente em área urbana com acúmulo de água parada e presença frequente de insetos, procura Unidade de Pronto Atendimento por dor articular intensa e persistente. Há 18 dias apresentou episódio de febre (38,8 ºC), com duração de 3 dias, associado à mialgia importante. Após a resolução da febre, evoluiu com dor, edema e limitação funcional em punhos e tornozelos bilateralmente. Nega sintomas respiratórios, gastrointestinais, oculares, manifestações hemorrágicas ou exantema cutâneo. Fez uso inicial de analgésicos comuns e iniciou anti-inflamatório não esteroidal há 5 dias, com melhora parcial da dor. Exame físico normal, exceto edema em punhos e tornozelos bilateralmente, associado à dor na palpação e limitação da mobilidade. Exames laboratoriais sem alterações, exceto proteína C reativa discretamente elevada. Considerando o quadro clínico, o exame adequado para confirmação do diagnóstico neste momento é detecção de"}}},{"id":"revalida_2026_1_q009","code":"REV-2026.1-Q009","campos":{"statement":{"antes_md5":"102531079f5fdd99da7fd4e24937202e","depois":"Menina, 8 anos, previamente hígida, é levada à Unidade de Pronto Atendimento com quadro de febre (39 a 40 °C) há 5 dias, associado à dor abdominal intensa, vômitos, exantema maculopapular em tronco e hiperemia conjuntival bilateral sem secreção. A mãe refere que a criança teve um quadro gripal leve há cerca de 4 semanas com teste de covid-19 positivo. Exame físico: prostrada; tempo de enchimento capilar de 4 segundos; pulsos finos; FC 135 bpm; PA 75 x 45 mmHg (abaixo do percentil 5 para idade e estatura); SatO₂ 91% em ar ambiente. Ausculta cardíaca revela ritmo de galope. Palpação abdominal mostra descompressão brusca negativa, mas com dor importante à palpação profunda. Qual é a principal suspeita clínica?"}}},{"id":"revalida_2026_1_q010","code":"REV-2026.1-Q010","campos":{"statement":{"antes_md5":"9464a88c8a5a9461087df53067303b59","depois":"Homem, 30 anos, vítima de colisão de motocicleta com poste há 50 minutos. Foi trazido pelo SAMU e encontra-se com vias aéreas pérvias; FR 32 irpm; murmúrio vesicular presente bilateralmente e SpO₂ 95% em ar ambiente. A pele está fria, o tempo de enchimento capilar lentificado, PA 75 x 45 mmHg, FC 128 bpm. Há escoriações em quadrante superior esquerdo do abdome e ausência de deformidades em membros. Glasgow 10 (O3 V3 M4), com pupilas isocóricas e fotorreagentes e sem evidências de trauma na região da cabeça. Realizado, à beira do leito, ultrassom FAST (Focused Assessment with Sonography for Trauma) que evidenciou grande quantidade de líquido livre na janela subdiafragmática esquerda. Após reanimação volêmica, PA 80 x 50 mmHg e FC 131 bpm. Diante do exposto, a conduta mais adequada é"}}},{"id":"revalida_2026_1_q014","code":"REV-2026.1-Q014","campos":{"statement":{"antes_md5":"62130bc8a2e9fb7c0ce90dd39c61ca6e","depois":"Mulher de 42 anos buscou Unidade Básica de Saúde com queixas de humor deprimido, anedonia, fadiga intensa, dificuldade de concentração e ganho de peso, associados a ressecamento da pele, constipação intestinal e irregularidade menstrual, por 2 meses. Foi diagnosticada com transtorno depressivo maior e começou tratamento com antidepressivo adequado, porém sem resposta clínica significativa após 12 semanas. Em consulta de retorno, relata manutenção dos sintomas, nega uso de outros medicamentos ou de drogas. Apresenta, ao exame, PA 110 x 80 mmHg; FC 64 bpm; FR 16 irpm; temperatura axilar de 37 ºC e glicemia capilar de 98 mg/dL. Nesse contexto, quais exames laboratoriais devem ser solicitados para o principal diagnóstico diferencial do caso?"}}},{"id":"revalida_2026_1_q015","code":"REV-2026.1-Q015","campos":{"statement":{"antes_md5":"ab09aba78ede2b0c1fb45049f47352f2","depois":"Adolescente de 15 anos, sexo masculino, procura Unidade Básica de Saúde relatando manchas cutâneas pruriginosas iniciadas nas últimas 24 horas, comprometendo todo o corpo. Relata diagnóstico recente de amigdalite, tendo iniciado por conta própria ibuprofeno há 7 dias. Antecedente de asma na infância e rinite alérgica. Nega febre, tosse ou diarreia, bem como alergias anteriores a medicamentos ou alimentos. Ao exame físico, 36,8 °C, eupneico, corado, anictérico. PA 110 x 70 mmHg; FC 86 bpm, FR 14 irpm, SatO₂ 98% em ar ambiente. Pele com eritema difuso, simétrico, papular, principalmente em tronco, mas também em membros, poupando palmas e plantas. Sem lesões, adenomegalias cervicais, axilares ou inguinais. Cavidade oral sem alterações. Exames laboratoriais apresentam os seguintes resultados: Exame Resultado Valor de referência Hemoglobina 14,5 g/dL 13 a 16 g/dL Hematócrito 45,3% 37 a 49% Leucócitos 5.650/mm³ 5.000 a 10.000/mm³ Bastonetes 0% -- Segmentados 52% -- Linfócitos típicos 38% -- Linfócitos atípicos 0% -- Eosinófilos 2% -- Plaquetas 185.000/mm³ 140.000 a 400.000/mm³ TGO 30 U/L 5 a 40 U/L TGP 32 U/L 4 a 32 U/L Ureia 28 mg/dL 16,6 a 48,5 mg/dL Creatinina 1,2 mg/dL 0,6 a 0,9 mg/dL Qual é a conduta mais adequada para o caso?","sem_tabela_md5":"897b1e047f74847be33bc4af39f43f8c"}}},{"id":"revalida_2026_1_q018","code":"REV-2026.1-Q018","campos":{"D":{"antes_md5":"db6880c58129acc46c6a4be4894e89df","depois":"IMC > 35 Kg/m²."}}},{"id":"revalida_2026_1_q023","code":"REV-2026.1-Q023","campos":{"statement":{"antes_md5":"53184da848b78725df0a673d7d3b3665","depois":"Recém-nascido, sexo masculino, nascido de parto vaginal a termo, com Apgar 8/9, pesando 2.860 g. Completou 30 horas de vida em aleitamento materno exclusivo, sem eliminação de mecônio. Há cerca de 6 horas, iniciou vômitos em jato, de coloração verde escura associados à distensão abdominal progressiva, irritabilidade intensa intercalada com prostração, e piora na aceitação das mamadas. Nas últimas 2 horas, evoluiu com desconforto respiratório e gemência. Exame físico: hipoativo, alternando irritabilidade com prostração e gemência, cianose perioral e extremidades frias. Temperatura 36,1 ºC; FC 188 bpm; FR 72 irpm; Tiragem subcostal e intercostal. Oximetria de pulso 89% em ar ambiente. Enchimento capilar 4 a 5 segundos. Fontanela normotensa. Abdome distendido, tenso, doloroso, com defesa involuntária; ruídos hidroaéreos diminuídos; sem massas palpáveis. Ao estímulo retal, ampola vazia, com eliminação de pequena quantidade de fezes fétidas e explosivas. O recém-nascido apresenta uma complicação grave como consequência de"}}},{"id":"revalida_2026_1_q024","code":"REV-2026.1-Q024","campos":{"statement":{"antes_md5":"af2481f20bf50ca7697e2b06d004f2a3","depois":"Homem de 45 anos dá entrada na Unidade de Pronto Atendimento com epistaxe anterior há cerca de 40 minutos. É hipertenso, fazendo uso irregular de fármaco anti-hipertensivo; nega trauma recente. Ao exame, apresenta sangramento visível no septo nasal anterior à esquerda, está hemodinamicamente estável e com vias aéreas pérvias. Após avaliação inicial e monitorização, a conduta mais adequada como primeira linha no manejo agudo desse paciente é realizar"}}},{"id":"revalida_2026_1_q026","code":"REV-2026.1-Q026","campos":{"statement":{"antes_md5":"977615537692d34f28b8ecd0a9586d26","depois":"Mulher, 50 anos, é trazida à Unidade Básica de Saúde (UBS) em área rural, distante 100 km da sede do município, relatando que há 5 dias iniciou com quadro de disúria, hematúria macroscópica, polaciúria e febre não aferida. Relata também calafrios, náuseas, vômitos, mialgia e dor lombar. Nega outras comorbidades ou alergias. Apresenta exame de urina realizado na véspera, com nitrito positivo, bactérias incontáveis e piúria. Ao exame físico, apresenta-se em estado geral regular; febril (39,3 ºC); FR 22 irpm; PA 89 x 52 mmHg; FC 104 bpm. Oximetria indica SpO₂ 96%. Sinal de Giordano positivo à esquerda. Sem outras alterações ao exame físico. Considerando que essa UBS conta com disponibilidade ideal dos medicamentos para o manejo inicial do caso, qual é a conduta adequada para essa paciente?"}}},{"id":"revalida_2026_1_q031","code":"REV-2026.1-Q031","campos":{"statement":{"antes_md5":"033968656a50f6e06f4d142a15e10a29","depois":"Homem, 28 anos, é admitido na sala de trauma de uma Unidade de Emergência vítima de colisão automobilística em alta velocidade com desaceleração súbita. Encontra-se consciente, queixa-se de dor torácica difusa. Ao exame, PA 110 x 70 mmHg, FC 110 bpm e oximetria de pulso de 96% (em ar ambiente); sem jugulares túrgidas ou assimetrias na expansibilidade torácica, percussão torácica timpânica bilateral e bulhas normofonéticas. Apresenta escoriações na parede anterior do tórax. A radiografia de tórax inicial revela mediastino alargado, apagamento do botão aórtico e desvio da traqueia para a direita. A principal hipótese diagnóstica é"}}},{"id":"revalida_2026_1_q032","code":"REV-2026.1-Q032","campos":{"statement":{"antes_md5":"2744b144627e2dd620ada5510a75fab5","depois":"Puérpera, 24 anos, imigrante recém-chegada ao Brasil, é admitida na maternidade 30 minutos após parto extra-hospitalar. Relata que o parto ocorreu rapidamente, sendo a placenta completamente expulsa alguns minutos após. Ao exame inicial, apresenta-se hemodinamicamente estável e com útero contraído, apesar de manter sangramento vaginal moderado. Ao exame do canal de parto, identifica-se laceração perineal envolvendo pele, mucosa vaginal e musculatura perineal, sem acometimento do esfíncter anal ou da mucosa retal. A paciente demonstra ansiedade, dificuldade de compreensão do idioma e questiona repetidamente o que será feito. Considerando a avaliação realizada e as boas práticas recomendadas pela OMS e pelo Ministério da Saúde para uma assistência humanizada, a conduta adequada é"}}},{"id":"revalida_2026_1_q045","code":"REV-2026.1-Q045","campos":{"D":{"antes_md5":"519082a7019e22b62602ba2142c61329","depois":"Autocoleta de material vaginal para pesquisa de DNA-HPV e, caso o resultado seja negativo, dispensar a paciente de novos exames de rastreamento."}}},{"id":"revalida_2026_1_q046","code":"REV-2026.1-Q046","campos":{"statement":{"antes_md5":"43e83e230cf78c31c8cada6b9c1b554d","depois":"Mulher, 67 anos, foi levada ao Pronto Socorro com falta de ar que iniciou há 3 horas, associada à dor torácica no hemitórax direito que piorava à inspiração profunda. Faz acompanhamento por hipertensão arterial e câncer de mama, em uso de hidroclorotiazida. Foi iniciada expansão volêmica e noradrenalina na Sala Vermelha por hipotensão e sonolência, e agora encontra-se vígil e orientada, PA 116 x 64 mmHg; FC 126 bpm; FR 20 irpm; SpO₂ 93% sob máscara não reinalante a 15 L/min. Tempo de enchimento capilar 4s. Exames complementares: eletrocardiograma taquicardia sinusal; troponina T ultrassensível 28 ng/L (VR < 14ng/L); creatinina sérica 2,1 mg/dL (VR: 0,5 a 0,9 mg/dL). Angiotomografia de tórax mostrou falha de enchimento em tronco de artéria pulmonar direita. Considerando o caso descrito, a conduta imediata adequada é prescrever"}}},{"id":"revalida_2026_1_q047","code":"REV-2026.1-Q047","campos":{"statement":{"antes_md5":"e33232006342186d8557dd8dfbbf4837","depois":"Uma menina de 7 anos é levada a ambulatório especializado pela mãe, que relata o aparecimento de pelos pubianos e aumento da região mamária há cerca de dois meses. Não há relato de uso de medicamentos, doenças crônicas ou exposição a substâncias hormonais. A criança apresenta estatura correspondente a escore Z igual a zero para a idade, sem desvio prévio documentado. Ao exame físico, observa-se tecido mamário palpável sob a aréola, sem separação do contorno mamário, compatível com Tanner M2, além de pelos pubianos escuros, grossos e levemente encaracolados, restritos à região labial, correspondendo a Tanner P2. Qual alteração no mecanismo fisiológico explica os achados descritos no caso?"}}},{"id":"revalida_2026_1_q049","code":"REV-2026.1-Q049","campos":{"statement":{"antes_md5":"0d6fdb565c199fb4474ad85c4f787689","depois":"Gestante, 33 anos, G2 P1 A0, cesariana há 3 anos por apresentação pélvica, fez pré-natal de baixo risco. Admitida na maternidade em trabalho de parto espontâneo, com apresentação cefálica, bolsa rota há 1 hora, com líquido amniótico claro e 6 cm de dilatação. Evoluiu de forma satisfatória sob monitorização fetal. Após 2 horas de evolução do trabalho de parto, passa a apresentar dor abdominal súbita, contínua e associada a mal-estar intenso e sangramento vaginal moderado. Ao exame: PA 82 x 42 mmHg; FC 134 bpm; FR 28 irpm; temperatura axilar 36,6 ºC; pele pálida, fria e sudoreica. Útero doloroso, mal definido e com partes fetais facilmente palpáveis; BCF 80 bpm sustentado; dilatação de 8 cm, plano -2 de De Lee, sangramento ativo e elevação da apresentação fetal. Diante desse quadro, qual deve ser a conduta imediata?"}}},{"id":"revalida_2026_1_q051","code":"REV-2026.1-Q051","campos":{"statement":{"antes_md5":"b699a0629be543b8f22ad068676b823f","depois":"Médica de uma Unidade Básica de Saúde atende um homem de 63 anos, 70 kg, IMC 25 kg/m², sedentário, motorista aposentado por invalidez após ter a visão comprometida por diabetes e hipertensão, diagnosticados há mais de 20 anos. O paciente faz uso de metformina e dapaglifozina em doses otimizadas. Faz autoaplicação de insulina NPH 56 UI ao acordar e 34 UI antes de dormir. Ao exame físico, são observados nódulos endurecidos ao redor da cicatriz umbilical, edema discreto em membros inferiores, sem outros achados. Exames laboratoriais recentes demonstram hemoglobina glicada de 8,2% (VR: 4,7 a 5,7%) e função renal preservada. O monitoramento da glicemia capilar apresenta valores em jejum entre 140 mg/dL a 160 mg/dL e pós-prandiais entre 180 mg/dL a 240 mg/dL, sem episódios de hipoglicemia. Qual é o plano terapêutico condizente com o papel dessa médica no trabalho em equipe multiprofissional?"}}},{"id":"revalida_2026_1_q056","code":"REV-2026.1-Q056","campos":{"statement":{"antes_md5":"5239004a66de922f5cbd4e9a8e5a2609","depois":"Uma técnica de enfermagem de uma Unidade Básica de Saúde (UBS), após coletar o sangue de um usuário, sofre um acidente perfurocortante com agulha previamente utilizada na coleta. Ela não se preocupou a princípio, pois tratava-se de exames de rotina e o paciente estava aparentemente saudável. Depois de 4 dias do ocorrido, por orientação de uma colega do trabalho, resolveu procurar a própria UBS para saber o que deveria ser feito. De acordo com os protocolos de vigilância em saúde do trabalhador sobre a Profilaxia Pós-Exposição (PEP) no caso específico do HIV, qual é a conduta adequada?"}}},{"id":"revalida_2026_1_q057","code":"REV-2026.1-Q057","campos":{"statement":{"antes_md5":"c640ff44a8de740e75ff44513fa61160","depois":"Mulher, 32 anos, foi internada em enfermaria de cirurgia para realização de toracotomia eletiva. No 3º dia pós-operatório, foi encontrada com alteração do nível de consciência e diversas cartelas de morfina vazias em sua bolsa. Além do rebaixamento do nível de consciência (escala de coma de Glasgow 8), a paciente apresentava pele fria e pegajosa; miose bilateral puntiforme; PA 100 x 60 mmHg; FC 56 bpm; FR 8 irpm; SatO₂ 86% em ar ambiente e temperatura axilar 36 ºC. Qual medicação é indicada para reversão do quadro?"}}},{"id":"revalida_2026_1_q059","code":"REV-2026.1-Q059","campos":{"statement":{"antes_md5":"a91ae451285a9cc264482e7eac1d4700","depois":"Lactente, 4 meses, é levado ao Setor de Urgência de um hospital por quadro de irritabilidade, vômitos e febre de até 39,5 ºC, iniciado há 10 horas. Mãe nega intercorrências gestacionais e neonatais. Exame físico: estado geral regular; prostrado; desidratado (2+/4+); gemente e com fontanela anterior abaulada. A pele apresenta exantema purpúrico e petéquias em membros inferiores. Recebeu as vacinas recomendadas pelo Plano Nacional de Imunizações até os 2 meses de vida. Considerando o diagnóstico, quais parâmetros da análise do líquido cefalorraquidiano e da bacterioscopia são esperados?"}}},{"id":"revalida_2026_1_q065","code":"REV-2026.1-Q065","campos":{"statement":{"antes_md5":"83bc3e5349f157214d530206c8a40345","depois":"Homem, 58 anos, hipertenso e tabagista, é admitido na Unidade de Pronto Atendimento com dor precordial em aperto, de início há 2 horas, irradiada para o membro superior esquerdo e para mandíbula, associada a náuseas e sudorese profusa. Ao exame físico: PA 150 x 90 mmHg, FC 88 bpm, FR 20 irpm, SatO₂ 93% em ar ambiente. Ausculta cardíaca e pulmonar sem alterações. O eletrocardiograma de 12 derivações, realizado em 8 minutos, revela inversão simétrica de onda T em V1 a V4, sem infra ou supradesnivelamento do segmento ST. Considerando o quadro clínico, qual é a conduta imediata adequada?"}}},{"id":"revalida_2026_1_q066","code":"REV-2026.1-Q066","campos":{"statement":{"antes_md5":"039599c948ec455dc0f4971e25a883c6","depois":"Menina, 7 anos, previamente saudável, é trazida pelos pais à Unidade de Pronto Atendimento de um hospital secundário devido à fadiga intensa há 3 dias, com piora progressiva. Nas últimas 24 horas, tornou-se muito sonolenta, com respiração rápida e profunda, descrita pelos pais como “barulhenta” e “ofegante”. Apresenta também dor abdominal difusa, náuseas e vômitos repetidos. Os pais negam tosse, febre e diarreia, mas relatam que a criança perdeu peso nas últimas semanas, apesar do aumento de apetite. Relatam aumento da ingesta de água e diurese abundante. Ao exame físico, a criança encontrava-se sonolenta; despertando com comandos verbais dos pais (Glasgow 13); mucosas secas; olhos encovados; FR 36 irpm, FC 138 bpm, PA 92 x 60 mmHg, SatO₂ 98% em ar ambiente; temperatura axilar 36,3 °C e enchimento capilar 2 segundos. Exames Iniciais Resultado Limites de normalidade Glicemia Capilar 392 mg/dl 70 a 105 mg/dl pH arterial 7,12 7,35 a 7,45 Bicarbonato 9 mEq/L 22 a 26 mEq/L Lactato 1,2 mmol/L 0,5 a 2,2 mmol/L Creatinina 0,5 mg/dL 0,3 a 0,9 mg/dL Ureia 32 mg/dL 11 a 38 mg/dL Sódio 132 mEq/L 135 a 145 mEq/L Potássio 4,8 mEq/L 3,4 a 5,0 mEq/L Leucócitos totais 15.200/mm³ 5.000 a 14.500/mm³ Plaquetas 150.000/mm³ 150.000 a 450.000/mm³ Considerando-se o caso, qual é a conduta terapêutica indicada?","sem_tabela_md5":"228399614dd6dc3748986cd4948c1d6b"}}},{"id":"revalida_2026_1_q068","code":"REV-2026.1-Q068","campos":{"statement":{"antes_md5":"3ba8676cbb17a04db446c34b0ffeba88","depois":"Mulher, 51 anos, comparece à consulta ginecológica na Unidade Básica de Saúde para apresentar mamografia realizada há 1 mês. Não apresenta queixas relacionadas à mama e não possui alterações no exame físico. Nega comorbidades e histórico familiar de doenças mamárias ou oncológicas. Mamografia bilateral. Mama esquerda: parênquima fibroglandular denso. Presença de calcificações pleomórficas finas, com distribuição segmentar, no quadrante ínfero-medial. Mama direita: parênquima fibroglandular denso. Ausência de achados significativos. Mamografia BI-RADS 4C. Considerando os achados mamográficos, qual é a conduta recomendada?"}}},{"id":"revalida_2026_1_q069","code":"REV-2026.1-Q069","campos":{"statement":{"antes_md5":"69521e31ca49b46295da70f864777969","depois":"Médica da Atenção Primária à Saúde (APS) acompanha uma adolescente de 16 anos com queixas persistentes de insônia, irritabilidade, isolamento social e queda do rendimento escolar. Após avaliação clínica presencial, a profissional realiza uma atividade síncrona, por meio de plataforma institucional, com um médico psiquiatra vinculado a um serviço localizado em outro estado, sem integração formal à rede assistencial da paciente, para discussão técnico-assistencial do caso e apoio à decisão clínica. A atividade ocorre exclusivamente entre os profissionais da saúde, sem a participação da adolescente ou de seus responsáveis na videoconferência. Considerando esse relato, qual é a interpretação e a explicação para a atividade realizada?"}}},{"id":"revalida_2026_1_q072","code":"REV-2026.1-Q072","campos":{"statement":{"antes_md5":"a66f588fc08885436e37e3f974fc2c7d","depois":"Homem preto, 68 anos, com hipertensão arterial sistêmica, doença renal crônica estágio clínico 3a com creatinina basal de 1,4 mg/dL é levado ao Pronto Atendimento com náusea, tontura e mal-estar geral. Faz uso regular de anlodipino 10 mg/dia, furosemida 80 mg/dia e enalapril 20 mg/dia. Ao exame físico, apresenta PA 90 × 60 mmHg, FC 96 bpm, FR 20 irpm, SatO₂ 95% em ar ambiente, tempo de enchimento capilar de 4 segundos, sem outras alterações. Os exames da admissão estão no quadro abaixo: Exame Resultado Valor de referência Creatinina sérica 1,9 mg/dL 0,7 a 1,2 mg/dL Ureia 124 mg/dL 10 a 50 mg/dL Potássio sérico 5,7 mEq/L 3,5 a 5,5 mEq/L Sódio sérico 145 mEq/L 135 a 145 mEq/L pH (gasometria venosa) 7,35 7,35 a 7,45 Bicarbonato (gasometria venosa) 20 mEq/L 22 a 26 mEq/L pCO₂ (gasometria venosa) 38 mmHg 35 a 45 mmHg Eletrocardiograma Sem alterações Com base nos dados do quadro, que condutas devem ser tomadas nesse momento?","sem_tabela_md5":"d8db03b00bf6c6604c3d0cf1d3f1e884"}}},{"id":"revalida_2026_1_q076","code":"REV-2026.1-Q076","campos":{"statement":{"antes_md5":"922e335a61cea8a9eb14ca264c2e1503","depois":"Homem trans, 30 anos, em uso de testosterona injetável há 6 anos, comparece à Unidade Básica de Saúde para consulta de rotina. Ele possui útero e colo uterino e nunca realizou exame citopatológico, devido a medo da dor e a desconforto com o procedimento. Ao exame físico, observa-se atrofia genital importante. O paciente deseja realizar o exame preventivo. No município ainda não está implantada a detecção de DNA-HPV. Nesse caso, a conduta adequada, com a respectiva justificativa, é"}}},{"id":"revalida_2026_1_q081","code":"REV-2026.1-Q081","campos":{"statement":{"antes_md5":"094eb39b46d9db091a6349cfb9a9eb6e","depois":"Homem, 38 anos, avaliado como risco anestésico ASA II (American Society of Anesthesiologists, 2024) irá ser submetido à colecistectomia videolaparoscópica eletiva, programada para iniciar às 16 h. Segundo o Projeto Aceleração da Recuperação Total Pós-Operatória (ACERTO) e as recomendações da Enhanced Recovery After Surgery Society (ERAS), qual conduta deve ser adotada quanto ao jejum pré-operatório?"}}},{"id":"revalida_2026_1_q087","code":"REV-2026.1-Q087","campos":{"statement":{"antes_md5":"555114d0d8f3365874e9ca413c269f81","depois":"Uma criança de 2 anos é levada ao Pronto Socorro com histórico de febre alta (39,8 °C), tosse persistente e dificuldade respiratória progressiva. Ao exame físico, apresenta FR 50 irpm; tiragem intercostal; batimento de asa nasal e estertores crepitantes difusos no hemitórax esquerdo; SatO₂ 88% em ar ambiente. A radiografia de tórax revela consolidação do lobo superior esquerdo. Qual é a conduta inicial adequada para esse caso?"}}},{"id":"revalida_2026_1_q091","code":"REV-2026.1-Q091","campos":{"statement":{"antes_md5":"56e3c9699dc18b8160068fbd7353dee7","depois":"Homem, 26 anos, é avaliado em ambulatório de especialidades após encaminhamento da Atenção Primária à Saúde por 4 episódios de icterícia leve nos últimos 2 anos. Os episódios são autolimitados e exacerbam-se sob estresse físico, jejum prolongado ou privação de sono. O paciente nega perda ponderal, dor abdominal, colúria, acolia fecal, comorbidades, etilismo ou uso de medicamentos. Ao exame físico, apresenta-se em bom estado geral, com discreta icterícia de escleras, sem visceromegalias. Restante do exame físico normal. Durante investigação ambulatorial, foram solicitados exames laboratoriais, cujos resultados foram semelhantes aos exames realizados durante os episódios anteriores de icterícia: Exame Resultado Valores de referência Bilirrubina total 3,2 mg/dL 0,3 a 1,2 mg/dL Bilirrubina indireta 2,8 mg/dL até 0,8 mg/dL Bilirrubina direta 0,3 mg/dL até 0,3 mg/dL AST (TGO) 22 U/L até 35 U/L ALT (TGP) 25 U/L até 35 U/L Fosfatase alcalina 82 U/L 30 a 120 U/L GGT 28 U/L 1 a 94 U/L Hemoglobina 14,5 g/dL 13,5 a 17,5 g/dL Reticulócitos 1,1% 0,5 a 2,0% LDH 178 U/L 100 a 190 U/L Haptoglobina 110 mg/dL 30 a 200 mg/dL Com base no quadro clínico e laboratorial e uso adequado de recursos em saúde, o médico deve","sem_tabela_md5":"a6e07609388fa53ff845e7a2bc8ee681"}}},{"id":"revalida_2026_1_q093","code":"REV-2026.1-Q093","campos":{"statement":{"antes_md5":"d1da69246120950d8ecefe852d121579","depois":"Um paciente de 45 anos encontra-se no 3º dia de pós-operatório de enterectomia extensa e jejunostomia por isquemia mesentérica em Unidade de Terapia Intensiva. Está em uso de ventilação mecânica e de drogas vasoativas. Qual a via alimentar mais adequada nesse caso?"}}},{"id":"revalida_2026_1_q094","code":"REV-2026.1-Q094","campos":{"statement":{"antes_md5":"9d06f16180f4f4da64e94b167584f5f6","depois":"Mulher, 38 anos, procura a Unidade Básica de Saúde relatando corrimento vaginal abundante, amarelo-esverdeado, acompanhado de prurido, ardor e desconforto durante a relação sexual. Refere também aumento do odor após a menstruação. Ao exame especular, observa-se colo hiperemiado com aspecto puntiforme. O pH vaginal é 5,5 e o teste de aminas é negativo. Diante do quadro clínico e desses achados, qual deve ser a conduta terapêutica no caso acima?"}}},{"id":"revalida_2026_1_q095","code":"REV-2026.1-Q095","campos":{"statement":{"antes_md5":"2c03668d53a626aeaf2b68ae057471b5","depois":"Uma Unidade de Saúde da Família em área de elevada incidência de dengue recebe João, 33 anos, sem comorbidades, apresentando febre há 2 dias, dor retro-orbitária, mialgia intensa e inapetência. Ao exame inicial: PA 118 x 76 mmHg; FC 92 bpm; tempo de enchimento capilar < 2 segundos; boa hidratação; ausência de dor abdominal e de sinais de sangramento. Hematócrito 42%; plaquetas 155.000/mm³. Foi liberado com analgésicos e hidratação oral. O paciente retorna após 2 dias relatando piora do estado geral, com vômitos persistentes, sensação de desmaio e dor abdominal contínua no quadrante superior direito, e diurese diminuída. Ao exame físico: PA 104 x 70 mmHg; FC 108 bpm; tempo de enchimento capilar 3 segundos; extremidades discretamente frias; dor à palpação do hipocôndrio direito; sinais de desidratação. Novo hemograma: hematócrito 46%; plaquetas 82.000/mm³. Considerando a propedêutica da dengue e a estratificação de risco por grupos, qual deve ser a conduta imediata?"}}},{"id":"revalida_2026_1_q096","code":"REV-2026.1-Q096","campos":{"statement":{"antes_md5":"2514ce338b4b908561992fa6a7dac2fa","depois":"Mulher, 68 anos, procurou a Unidade de Pronto Atendimento com quadro de dor súbita, calor e edema importante em joelho direito, iniciado há 24 horas, que a impede de deambular. Faz acompanhamento regular por diabetes mellitus tipo 2 e osteoartrite de joelhos, em uso de metformina e gliclazida. Ao exame físico, apresenta bom estado geral, lúcida e orientada; PA 135 x 85 mmHg; FC 98 bpm; FR 18 irpm e temperatura axilar 37,9 ºC. O joelho direito apresenta-se com volumoso derrame articular, eritema e dor à mobilização passiva e ativa. Exames laboratoriais: Exame Resultado Valor de referência Hemoglobina 12,2 g/dL 11,5 a 13,5 g/dL Leucócitos 13.400/mm³ 5.000 a 15.000/mm³ Creatinina 1,1 mg/dL 0,5 a 0,9 mg/dL Proteína C Reativa 8,5 mg/L < 5mg/L Nessa situação, qual conduta deve ser adotada?","sem_tabela_md5":"dbc16e8619a5f8a563482255eb797c43"}}},{"id":"revalida_2026_1_q100","code":"REV-2026.1-Q100","campos":{"statement":{"antes_md5":"570417ed68e4bca7be1079661f913b18","depois":"Um menino de 5 anos comparece ao acolhimento da Unidade Básica de Saúde com a babá, a pedido da escola, por suspeita de conjuntivite. Relata que a criança estava bem até voltar de férias escolares há 1 semana; está preocupada, pois sabe que os pais são contra a vacinação obrigatória. Há 4 dias com febre, resfriado, tosse seca, olhos vermelhos, vômitos e inapetência, medicado com paracetamol pela família por conta própria, sem melhora. No dia da consulta, o paciente acordou com lesões no rosto, atribuídas a uma reação ao uso do paracetamol. Ao exame: hidratado, prostrado, temperatura axilar 39 ºC, hiperemia conjuntival bilateral leve, exantema papular em face, presença de máculas branco-azuladas de 1 a 3 mm com halo eritematoso em mucosa da boca. Sem outras alterações. De acordo com as diretrizes do Ministério da Saúde e com base no quadro clínico e epidemiológico mais provável, o tratamento desse paciente deve incluir"}}}]$carga_dados$::jsonb;
  r jsonb;
  c record;
  q public.questions;
  v_statement text;
  v_options jsonb;
  v_atual text;
  v_situacao text;
  v_muda boolean;
  v_analises integer := 0;
begin
  perform set_config('sqie.reason', 'Texto fiel ao caderno oficial do Inep (carga das provas corrigidas, revisão de 12/10/2026)', true);
  for r in select value from jsonb_array_elements(v_dados) loop
    select * into q from public.questions x where x.id = r ->> 'id' for update;
    if not found then
      insert into _carga_texto_resultado values ('revalida-2026-1', r ->> 'id', r ->> 'code', '-', 'pulado: questão não encontrada no banco');
      continue;
    end if;
    v_statement := q.statement;
    v_options := q.options;
    v_muda := false;
    for c in select key as campo, value as v from jsonb_each(r -> 'campos') loop
      v_atual := case when c.campo = 'statement' then q.statement
                      else (select o ->> 'text' from jsonb_array_elements(q.options) o where o ->> 'id' = c.campo limit 1) end;
      if v_atual is not distinct from (c.v ->> 'depois') or md5(v_atual) is not distinct from (c.v ->> 'sem_tabela_md5') then
        v_situacao := 'já estava corrigido';
      elsif v_atual is not null and md5(v_atual) = c.v ->> 'antes_md5' then
        v_situacao := 'corrigido agora';
        v_muda := true;
        if c.campo = 'statement' then
          v_statement := c.v ->> 'depois';
        else
          v_options := (select jsonb_agg(case when o ->> 'id' = c.campo then jsonb_set(o, '{text}', to_jsonb(c.v ->> 'depois')) else o end order by n)
                        from jsonb_array_elements(v_options) with ordinality as x (o, n));
        end if;
      else
        v_situacao := 'pulado: o texto no banco mudou depois de 12/10/2026';
      end if;
      insert into _carga_texto_resultado values ('revalida-2026-1', q.id, q.code, case c.campo when 'statement' then 'enunciado' else 'alternativa ' || c.campo end, v_situacao);
    end loop;
    if v_muda then
      v_analises := v_analises + (select count(*)::int from public.question_analysis a where a.question_id = q.id and a.is_current and a.status = 'published');
      update public.questions set statement = v_statement, options = v_options where id = q.id;
      perform public.admin_log('question.updated', q.id, jsonb_build_object('status', q.status, 'reason', 'Texto fiel ao caderno oficial do Inep (carga das provas corrigidas, revisão de 12/10/2026)'));
    end if;
  end loop;
  insert into _carga_texto_resultado values ('revalida-2026-1', '-', '-', 'análises', 'análises publicadas que saíram do ar: ' || v_analises);
  perform set_config('sqie.reason', '', true);
end
$carga_texto$;

select resultado, detalhe from (
  select 0 as ordem,
         case when count(*) filter (where situacao like 'pulado%') = 0 then 'OK: ' else 'ATENÇÃO: ' end
           || 'Revalida 2026/1: '
           || count(distinct questao) filter (where situacao = 'corrigido agora') || ' questões corrigidas agora ('
           || count(*) filter (where situacao = 'corrigido agora') || ' campos); '
           || count(*) filter (where situacao = 'já estava corrigido') || ' campos já estavam corrigidos; '
           || count(*) filter (where situacao like 'pulado%') || ' pulados (de 35)' as resultado,
         max(situacao) filter (where campo = 'análises') as detalhe
  from _carga_texto_resultado where prova = 'revalida-2026-1'
  union all
  select 1, 'PULADO: ' || codigo || ' (' || campo || ')', situacao
  from _carga_texto_resultado where prova = 'revalida-2026-1' and situacao like 'pulado%'
) x order by ordem, resultado;
